// Base case: Apply Simpson's rule directly for small intervals or when precision is met
    double h = (b - a) / 2;
    double c = (a + b) / 2;
    double fa = f(a);
    double fc = f(c);
    double fb = f(b);
    double s1 = (h / 3) * (fa + 4 * fc + fb); // Coarse estimate

    // Recursive case: Subdivide the interval and refine the estimate
    double h2 = h / 2;
    double c1 = a + h2;
    double c2 = b - h2;
    double fc1 = f(c1);
    double fc2 = f(c2);
    double s2 = (h2 / 3) * (fa + 4 * fc1 + 2 * fc + 4 * fc2 + fb); // Refined estimate

    // Error control
    if (std::abs(s2 - s1) < precision) {
        return s2; // Precision achieved, return the refined estimate
    } else {
        // Recursively refine the estimates for the two halves
        return adaptive_simpson(f, a, c, precision / 2) + adaptive_simpson(f, c, b, precision / 2);
    }

